function planningConversation(p){const q=M.planning(p),question=M.planningQuestions(p)[0],src=p.source;return CreationWorkbench.conversation({title:'描述你的灵感或创意',hint:'短篇漫画策划；本机按已有段落建立草稿，未接模型扩写。',sourceHtml:`${src?`<div class="cs-plan-source"><strong>来源：${esc(src.title)}</strong><p>${esc((src.characters||[]).map(c=>c.name).join('、'))||'人物未登记'} · ${src.episodeIds.length}集，来源原文完整保留</p>${src.outline.length>1?`<label>本次短篇改编范围<select id="planRange"><option value="">选择本次改编范围</option><option value="full" ${q.rangeId==='full'?'selected':''}>整部内容</option>${src.outline.map(e=>`<option value="${esc(e.id)}" ${q.rangeId===e.id?'selected':''}>${esc(e.title)}</option>`).join('')}</select></label>`:'<p>本次以所选单集为改编范围。</p>'}<small>完整短篇可选整部内容；长篇建议选某一集。请确认范围适合本次篇幅；尚不支持自动摘选或压缩全书。</small></div>`:''}`,seed:q.started?(src?src.title:q.seed):'',messages:q.messages,questionHtml:`${q.started&&!q.generated&&question?`<article class="question"><b>一起完善 · ${q.answers.length+1}/最多4轮</b><p>${esc(question.text)}</p><div class="actions">${question.options.map(t=>`<button data-plan-answer="${esc(t)}">${esc(t)}</button>`).join('')}</div></article>`:''}`,composerHtml:`<label>${!q.started?'描述一个短篇漫画创意':q.generated?'继续讨论和调整策划':'回答这一题，也可交给AI'}<textarea id="planComposer" rows="3" placeholder="${q.manualCharacters?'写下主角、配角和关系…':q.started?'写下你的想法…':'一句话也可以，例如：两位陌生人在停电的电梯里交换秘密。'}">${esc(q.composer)}</textarea></label><div class="actions"><button id="planSend" class="primary">${q.started?'发送':'开始策划'}</button>${q.started&&!q.generated?'<button data-plan-answer="交给AI">交给AI</button>':''}<button id="planGenerate">${q.generated?'重新整理策划':'直接整理策划'}</button></div>`});}
function planningView(p){const q=M.planning(p),question=M.planningQuestions(p)[0],u=unitName(q.meta.format),src=p.source;return `<div class="cs-plan-grid">${planningConversation(p)}<section class="cs-plan-reading">${planningResult(p)}${src?sourceInfo(p):''}</section></div>`;}

function planningResult(p){const original=M.planning(p),editing=planEdit?.id===p.id,q=editing?planEdit.draft:original,u=unitName(q.meta.format);return `<div class="sectionHead"><h2>漫画策划</h2><span class="hint">对话整理 · 本机演示</span>${editing?'<div class="actions"><button id="planEditDone">完成</button><button id="planEditCancel">取消</button></div>':'<button id="planEdit">编辑</button>'}</div>${editing?`<div class="cs-plan-meta"><label>作品名<input data-plan-meta="title" value="${esc(q.meta.title)}"></label><label>篇幅（${u}数）<input id="planCount" type="number" min="1" max="30" value="${q.proposedCount??q.meta.count}"></label><label>目标读者<input data-plan-meta="audience" value="${esc(q.meta.audience)}" placeholder="待确定"></label><label>故事题材<input data-plan-meta="genre" value="${esc(q.meta.genre)}" placeholder="如爱情 / 悬疑"></label><label>漫画形式<select id="planFormat">${Object.entries(formats).map(([k,v])=>`<option value="${k}" ${(q.proposedFormat||q.meta.format)===k?'selected':''}>${v}</option>`).join('')}</select></label><label>画风<input data-plan-meta="style" value="${esc(q.meta.style)}" placeholder="待确定"></label><label class="wide">背景 / 世界观<input data-plan-meta="world" value="${esc(q.meta.world)}" placeholder="待确定；不自动补造"></label></div><div class="actions"><span>完成后可应用篇幅 / 形式</span><small class="hint">${q.meta.format==='four'?'每组4格，后续编排':q.meta.format==='single'?'每幅单图':'短篇可先试4—8'+u} · 多卷长篇请先去故事创作</small></div><label>整体故事简介<textarea id="planSynopsis" rows="3" placeholder="整理后保留创意或来源，可直接写成故事简介">${esc(q.synopsis)}</textarea></label>${q.pages.length?q.pages.map((x,i)=>`<article class="cs-plan-unit"><h3>第${i+1}${u}${q.meta.format==='four'?' · 四格一组':''}</h3><label>发生什么 / 转折或承接<textarea data-plan-page="${i}" rows="3" placeholder="待创作：写本${u}推进的内容，不重复填充原句">${esc(x.text)}</textarea></label></article>`).join(''):'<div class="empty">先聊聊创意，或直接整理；这里将显示逐页梗概，不提前拆格。</div>'}`:`${!q.generated?'<p class="hint">和左侧聊聊创意，整理后的策划会显示在这里，无需逐项填写。</p>':''}<dl class="cs-plan-facts">${[['作品名',q.meta.title==='My new comic'?'待讨论':q.meta.title],['篇幅',q.meta.count+u+' · '+(q.generated?'当前策划':'演示默认，可在对话中确定')],['目标读者',q.meta.audience],['故事题材',q.meta.genre],['漫画形式',formats[q.meta.format]],['画风',q.meta.style],['背景 / 世界观',q.meta.world]].map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v||'待讨论')}</dd></div>`).join('')}</dl>${q.proposedCount!==undefined||q.proposedFormat!==undefined?'<div class="actions"><span class="hint">篇幅 / 形式有待应用变更</span><button id="planReflow">应用篇幅 / 形式</button></div>':''}<article class="cs-plan-summary"><h3>整体故事简介</h3><p>${esc(q.synopsis||'对话后整理到此；本机演示不自动扩写故事。')}</p></article>${q.pages.length?q.pages.map((x,i)=>`<article class="cs-plan-unit"><h3>第${i+1}${u}${q.meta.format==='four'?' · 四格一组':''}</h3><p>${esc(x.text||'本页内容尚待讨论；本机未自动补写。')}</p></article>`).join(''):'<div class="empty">逐页梗概将在对话整理后展示。</div>'}` }`;}
function wireContent(){const p=P(),d=M.contentDesk(p),act=fn=>{try{fn();save();render();}catch(e){$('stageMessage').textContent=e.message;}};const confirmReplace=()=>!p.story&&!d.draft.length||confirm('替换当前内容草稿？原输入、历史稿、来源与后续资产/编排/图层均保留，后续需核对。');if($('contentTitle'))$('contentTitle').oninput=e=>{p.title=e.target.value;save();updateProjectList();};host.querySelectorAll('[data-content-tab]').forEach(b=>b.onclick=()=>act(()=>{d.tab=b.dataset.contentTab;}));if($('contentInput'))$('contentInput').oninput=e=>{d.input=e.target.value;save();};if($('contentRequest'))$('contentRequest').oninput=e=>{d.request=e.target.value;save();};if($('organizeContent'))$('organizeContent').onclick=()=>act(()=>{if(!d.input.trim())throw Error('请先描述想画的内容。');if(d.draft.length&&!confirmReplace())return;d.draftHistory??=[];d.draftHistory.push(clone(d.draft));M.organizeContent(p);});if($('sendContentRequest'))$('sendContentRequest').onclick=()=>act(()=>M.requestContent(p));if($('editContent'))$('editContent').onclick=()=>act(()=>{d.editing=!d.editing;});host.querySelectorAll('[data-content-unit]').forEach(el=>el.oninput=()=>{d.draft[+el.dataset.contentUnit].text=el.value;save();$('contentState').textContent='内容草稿待采用';});if($('adoptContent'))$('adoptContent').onclick=()=>act(()=>{if(p.story&&p.story!==M.currentContent(p)&&!confirm('采用新内容？已有编排、图片、图层保留并标记待核对。'))return;M.adoptContent(p);});if($('contentAsset'))$('contentAsset').onchange=e=>act(()=>{d.assetId=e.target.value;d.episodeId=chosenContentAsset()?.outline[0]?.id||'';});host.querySelectorAll('[data-content-scope]').forEach(b=>b.onclick=()=>act(()=>{d.scope=b.dataset.contentScope;}));if($('contentEpisode'))$('contentEpisode').onchange=e=>act(()=>{d.episodeId=e.target.value;});if($('confirmContentAsset'))$('confirmContentAsset').onclick=()=>act(()=>{const a=chosenContentAsset();if(!a)throw Error('请选择已保存故事资产。');const ids=d.scope==='full'?a.outline.map(e=>e.id):[d.episodeId];if(ids.some(id=>!M.assetBody(a,a.outline.find(e=>e.id===id)).trim()))throw Error('所选范围有集缺少正文，请先回故事保存完整正文。');if(!confirmReplace())return;d.draftHistory??=[];d.draftHistory.push(clone(d.draft));M.useContentAsset(p,a,ids);M.planningFromSource(p);});}
function wirePlanning(){if(!$('planComposer'))return;if($('epCharacters')){wireEpisodeConversation();return;}const p=P(),actual=M.planning(p),q=planEdit?.id===p.id?planEdit.draft:actual,run=fn=>{try{if(planEdit?.id===p.id)throw Error('请先完成或取消右侧临时编辑。');fn();save();render();const log=host.querySelector('.cs-plan-log');if(log){const question=log.querySelector('.question');log.scrollTop=question?question.offsetTop-log.offsetTop:log.scrollHeight;}}catch(e){$('stageMessage').textContent=e.message;}};if($('planEdit'))$('planEdit').onclick=()=>{planEdit={id:p.id,draft:clone(actual)};render();};if($('planEditCancel'))$('planEditCancel').onclick=()=>{planEdit=null;render();};if($('planEditDone'))$('planEditDone').onclick=()=>{if(JSON.stringify(actual)!==JSON.stringify(q)){actual.archives??=[];actual.archives.push({meta:clone(actual.meta),synopsis:actual.synopsis,pages:clone(actual.pages)});for(const k of ['meta','synopsis','pages','proposedCount','proposedFormat']){if(q[k]===undefined)delete actual[k];else actual[k]=clone(q[k]);}}planEdit=null;save();render();};const changed=()=>{if(!planEdit)save();};$('planComposer').oninput=e=>{q.composer=e.target.value;save();};const say=text=>{if(!p.source&&/长篇|多卷|长达.*集|[百千]集|long[- ]?form|multi[- ]?volume|epic saga/i.test(text)){q.messages.push({role:'assistant',text:'这更适合长篇规划。请先到故事创作完成规划，再从故事资产选择本次短篇改编范围。'});q.composer='';return false;}M.planningSay(p,text);return true;};$('planSend').onclick=()=>run(()=>say(q.composer));host.querySelectorAll('[data-plan-answer]').forEach(b=>b.onclick=()=>{if(b.dataset.planAnswer==='我来设定'){q.manualCharacters=true;save();$('planComposer').placeholder='写下主角、配角和关系…';$('planComposer').focus();return;}run(()=>M.planningSay(p,b.dataset.planAnswer));});host.querySelectorAll('[data-plan-meta]').forEach(el=>el.oninput=()=>{q.meta[el.dataset.planMeta]=el.value;changed();});if($('planSynopsis'))$('planSynopsis').oninput=e=>{q.synopsis=e.target.value;changed();};host.querySelectorAll('[data-plan-page]').forEach(el=>el.oninput=()=>{q.pages[+el.dataset.planPage].text=el.value;changed();});if($('planCount'))$('planCount').oninput=e=>{q.proposedCount=e.target.value;};if($('planFormat'))$('planFormat').onchange=e=>{q.proposedFormat=e.target.value;};const generate=()=>{if(p.source?.outline.length>1&&!q.rangeId)throw Error('请先选择本次短篇改编范围：整部内容或某一集；整部来源会完整保留。');if(q.rangeId==='full'&&!confirm('确认整部内容适合本次漫画篇幅？本机只顺序分配原文，不会自动摘选或压缩全书。长篇建议取消后选某一集；若需摘选段落，请先人工准备本次范围。'))return;if(!q.started&&q.composer.trim()){if(say(q.composer)===false)throw Error('请先去故事创作规划长篇，再选择短篇改编范围。');}if(q.pages.length&&!confirm('重新分配将替换当前页纲，手改完整归档；已有编排和图层不变，是否继续？'))return;M.planningGenerate(p,Number(q.proposedCount??q.meta.count),q.proposedFormat||q.meta.format);delete q.proposedCount;delete q.proposedFormat;};$('planGenerate').onclick=()=>run(generate);if($('planReflow'))$('planReflow').onclick=()=>run(generate);if($('planRange'))$('planRange').onchange=e=>run(()=>{if(q.generated&&!confirm('切换本次改编范围？旧策划保留，需明确重新整理，不覆盖已有页面。'))return;if(q.generated){q.archives??=[];q.archives.push({meta:clone(q.meta),pages:clone(q.pages),synopsis:q.synopsis});}q.rangeId=e.target.value;q.rangeText=q.rangeId==='full'?p.source.content:q.rangeId?M.assetBody(p.source,p.source.outline.find(e=>e.id===q.rangeId)):'';q.synopsis='';q.generated=false;});}
function wireFields(){host.querySelectorAll('[data-field]').forEach(el=>el.oninput=()=>{let path=JSON.parse(el.dataset.field),o=P();for(let k of path.slice(0,-1))o=o[k];o[path.at(-1)]=el.value;if(path[0]==='title')for(let arr of Object.values(P().edit)){let t=arr.find(t=>t.id==='title');if(t)t.text=P().title;}if(path[0]==='scenes'&&path.includes('action')){const drafts=host.querySelectorAll('.cs-draft-grid article p');if(drafts[Number(path[3])])drafts[Number(path[3])].textContent=el.value||'待填写画面';}if(path[0]==='scenes'&&path.includes('dialogue')){const drafts=host.querySelectorAll('.cs-draft-grid article small');if(drafts[Number(path[3])])drafts[Number(path[3])].textContent=el.value||'无对白';}if(path.includes('dialogue'))syncDialogue(Number(path[1]),Number(path[3]),el.value);save();globalStatus();});}
