function wireEpisodeArrangement(){wireArrangementPreview();save();const p=P(),es=M.episodes(p),e=es.find(e=>e.id===p.activeEpisodeId),s=p.scenes[p.scene]?.episodeId===e.id?S():null,run=fn=>{try{fn();save();render();}catch(err){$('stageMessage').textContent=err.message;}},bind=(id,evt,fn)=>{if($(id))$(id)[evt]=fn;};host.querySelectorAll('[data-ea-episode]').forEach(b=>b.onclick=()=>run(()=>{p.activeEpisodeId=b.dataset.eaEpisode;const i=p.scenes.findIndex(s=>s.episodeId===p.activeEpisodeId&&!s.previousEpisodeDraft);if(i>=0)p.scene=i;compositionPanel=0;}));host.querySelectorAll('[data-ea-page]').forEach(b=>b.onclick=()=>run(()=>{p.scene=+b.dataset.eaPage;compositionPanel=0;}));bind('eaBudget','oninput',ev=>{e.pageBudget=ev.target.value;save();});bind('eaRecommend','onclick',()=>{e.pageBudget=p.source?Math.max(1,Math.min(8,(e.text||'').split(/\n\s*\n/).filter(x=>x.trim()).length)):p.planning?.adopted?.pages?.length||1;$('eaBudget').value=e.pageBudget;save();$('eaRecommendNote').textContent='建议'+e.pageBudget+'页：仅按已有段落 / 策划演示，请确认预算。';});const split=()=>run(()=>{if(p.scenes.some(s=>s.episodeId===e.id)&&!confirm('重新拆页会新增本次页稿；原页、手改格子及图层完整保留并归档，标记待核对。继续？'))return;M.splitEpisode(p,e.id,$('eaBudget').value);});bind('eaSplit','onclick',split);bind('eaInitialSplit','onclick',split);bind('eaAddPage','onclick',()=>run(()=>{M.page(p);S().episodeId=e.id;}));if(!s)return;const panel=s.panels[compositionPanel];host.querySelectorAll('[data-ea-panel]').forEach(b=>b.onclick=()=>run(()=>{compositionPanel=+b.dataset.eaPanel;P().arrangementPanelId=S().panels[compositionPanel].id;}));bind('eaBeat','oninput',ev=>{s.beat=ev.target.value;save();});bind('eaBeat','onchange',()=>run(()=>{}));bind('eaAction','oninput',ev=>{panel.action=ev.target.value;s.compositionTouched=true;save();paintArrangementPreview();const label=host.querySelector('.ea-panel.selected .ea-panel-head span');if(label)label.textContent=panel.action||'待补充画面，不自动凑字';});bind('eaDialogue','oninput',ev=>{panel.dialogue=ev.target.value;updateArrangementDialogue(p,s,panel);s.compositionTouched=true;save();paintArrangementPreview();});host.querySelectorAll('[data-ea-asset]').forEach(el=>el.onchange=()=>{panel.visualAssetRefs=p.assets.filter(a=>host.querySelector(`[data-ea-asset="${a.id}"]`)?.checked).map(a=>({assetId:a.id,versionId:a.adoptedVisualId}));save();});bind('eaGenerate','onclick',()=>run(()=>{if(s.contentGenerated&&!confirm('重新生成将归档本页全部旧格、图片、文字与版本引用；新稿按待选模板建立。取消保持现稿，继续？'))return;M.generatePageContent(p,p.scene);compositionPanel=0;}));host.querySelectorAll('[data-ea-template]').forEach(b=>b.onclick=()=>run(()=>M.choosePageTemplate(p,s,b.dataset.eaTemplate,+b.dataset.eaCount)));bind('eaRegeneratePanel','onclick',()=>run(()=>{panel.regenerationRequests??=[];panel.regenerationRequests.push({at:new Date().toISOString(),action:panel.action,dialogue:panel.dialogue});$('stageMessage').textContent='已记录单格重生成要求，未接模型、内容未自动融合。';}));}
function pageTemplateChooser(p,s,si){
 const catalog=M.templateCatalog(p.format),recommended=M.recommendPageTemplates(p,si),label=key=>catalog.find(t=>t.key===key)?.label||({balance:'均衡旧版',focus:'重点旧版',sequence:'连续旧版',legacy:'保留原稿'}[key]||key);
 const thumb=item=>{const l=M.templateLayout(p.format,item.count,item.key);return `<svg viewBox="0 0 ${l.width} ${l.height}" role="img" aria-label="${esc(item.label)}，${item.count}格，按数字阅读">${l.boxes.map((b,i)=>`<rect class="${i===item.focal?'ea-template-focal':''}" x="${b.x}" y="${b.y}" width="${b.w}" height="${b.h}"/><text x="${b.x+b.w/2}" y="${b.y+b.h/2+26}" text-anchor="middle" font-size="90">${i+1}</text>`).join('')}</svg>`;};
 const card=(item,rank)=>{const pending=s.pendingTemplate?.key===item.key&&s.pendingTemplate.count===item.count,applied=s.appliedTemplate?.key===item.key&&s.appliedTemplate.count===item.count;return `<button class="ea-template-card ${applied?'is-applied':''}" data-ea-template="${item.key}" data-ea-count="${item.count}" aria-pressed="${pending}" title="${esc(item.purpose)}">${thumb(item)}<span><b>${rank?'推荐'+rank+' · ':''}${esc(item.label)}</b><small>${item.count}格 · ${esc(item.purpose)}</small><em>${pending?'待应用':applied?'当前已应用':'选择此模板'}</em>${item.reasons?`<small class="ea-template-reason">${esc(item.reasons.join('；'))}</small>`:''}</span></button>`;};
 return `<div class="ea-template-state"><strong>${s.appliedTemplate?'当前：'+label(s.appliedTemplate.key)+' · '+s.appliedTemplate.count+'格':'当前尚未生成内容'}</strong>${s.pendingTemplate?`<span>待应用：${esc(label(s.pendingTemplate.key))} · ${s.pendingTemplate.count}格</span><small>点击左上“生成本页内容”后应用；下方预览仍保留当前稿。</small>`:'<small>选择模板只记录草稿，确认生成后才联动每格内容与预览。</small>'}</div><h4 class="ea-template-heading">AI推荐 · 规则演示</h4><small class="ea-template-boundary">按本页剧情、信息量与相邻页节奏评分，未接模型；深色格为主画面，数字为读序。</small><div class="ea-template-recommendations">${recommended.map((item,i)=>card(item,i+1)).join('')}</div><details class="ea-template-library"><summary>完整模板库 · ${catalog.length}种叙事结构</summary><div class="ea-template-gallery">${catalog.map(item=>card(item)).join('')}</div></details>`;
}

function arrangementPreviewView(s){return `<section class="ea-preview"><div class="ea-preview-heading"><h3>分镜排版草稿</h3><button id="eaRead" ${!s?.contentGenerated?'disabled':''}>放大阅读</button></div><p class="hint">${s?.pendingTemplate?'待应用 '+s.pendingTemplate.count+'格；下方仍为当前已应用版':s?.contentGenerated?'当前已应用版 · 点击格框定位编辑':'先选择模板并生成本页内容'}</p><div class="ea-preview-scroll"><div id="eaPreviewPaper"><canvas id="eaPreviewCanvas" aria-label="当前已应用分镜草稿"></canvas><div id="eaPreviewHits"></div></div></div><p id="eaPreviewStatus" class="hint">仅展示格框、读序、画面说明与对白占位；成图请到第4步查看。</p></section>`;}
function updateArrangementDialogue(p,s,panel){const key=p.scene+':'+p.format+(p.format==='single'?':'+(s.singleIndex||0):'');let texts=p.edit[key];if(!texts){texts=M.letters(p,p.scene,p.format);texts=p.edit[key];}const targets=texts.filter(t=>!t.archivedPanel&&(t.panelId===panel.id||(!t.panelId&&t.panel===compositionPanel)));if(targets.length){targets[0].text=panel.dialogue;return;}if(!panel.dialogue.trim())return;const box=M.pageLayout(p,p.scene).boxes[p.format==='single'?0:compositionPanel];texts.push({id:'letter-'+panel.id+'-'+Date.now(),name:'第'+(compositionPanel+1)+'格文字',panel:compositionPanel,panelId:panel.id,type:'dialogue',text:panel.dialogue,x:box.x+box.w*.08,y:box.y+28,w:Math.min(350,box.w*.68),h:100,size:25,tailX:box.x+box.w*.6,tailY:box.y+Math.min(box.h-30,180)});}
